tweaks.command:
PKG={{pkg}}
if pm list packages -u | sed 's/^package://' | grep -qx "$PKG"; then :; else echo "没有这个包：$PKG"; exit 1; fi
if pm disable-user --user 0 "$PKG" 2>&1; then echo "已停用 $PKG"; else echo "停用被拒绝 DISABLE_REFUSED"; exit 1; fi

